*** Update File: /Users/lainniay/Code/Cpp/WebServer/report.md
@@
 ### 4. 核心代码
+
+本节选取项目中最能体现 WebServer 工作流程的核心代码进行说明。代码片段主要覆盖服务器启动、连接分发、HTTP 请求解析、HTTP 响应构造、业务路由、配置文件解析、异步日志以及用户认证等部分。
+
+#### 4.1 Socket 创建、端口绑定与监听
+
+服务器启动的核心逻辑位于 `Server::start()`。该函数按照“创建 Socket、配置 Socket、绑定端口并监听”的顺序完成服务器初始化。
+
+```cpp
+Result<void> Server::start() {
+    // 如果 server_fd 已经不是 -1，说明服务器已经启动过，不能重复启动
+    if (this->server_fd != -1) {
+        return std::unexpected(make_err(ErrCode::ServerAlreadyStarted));
+    }
+
+    // 创建服务器 Socket，成功后返回文件描述符
+    auto res = create_server();
+    if (!res) {
+        return std::unexpected(res.error());
+    }
+
+    // 保存服务器 Socket 文件描述符，后续 bind、listen、accept 都依赖它
+    this->server_fd = res.value();
+
+    // 配置 Socket 选项，例如是否允许端口复用
+    if (auto config_res = config_server(); !config_res) {
+        return std::unexpected(config_res.error());
+    }
+
+    // 将 Socket 绑定到指定端口，并开始监听客户端连接
+    if (auto bind_res = bind_and_listen(); !bind_res) {
+        return std::unexpected(bind_res.error());
+    }
+
+    return {};
+}
+```
+
+其中，`create_server()` 负责调用系统接口创建 TCP Socket，`bind_and_listen()` 负责绑定端口并进入监听状态。
+
+```cpp
+Result<int> Server::create_server() {
+    // AF_INET 表示使用 IPv4，SOCK_STREAM 表示使用 TCP 字节流
+    int fd = ::socket(AF_INET, SOCK_STREAM, 0);
+    if (fd == -1) {
+        return std::unexpected(make_err(ErrCode::SocketCreateFailed, errno));
+    }
+    return fd;
+}
+
+Result<void> Server::bind_and_listen() {
+    sockaddr_in address{};
+    address.sin_family = AF_INET;           // 使用 IPv4 地址族
+    address.sin_addr.s_addr = INADDR_ANY;   // 监听本机所有网卡地址
+    address.sin_port = htons(config.port);  // 将端口号转换为网络字节序
+
+    // 将服务器 Socket 绑定到指定 IP 和端口
+    if (::bind(this->server_fd, reinterpret_cast<struct sockaddr*>(&address),
+               sizeof(address)) < 0) {
+        return std::unexpected(make_err(ErrCode::BindFailed, errno));
+    }
+
+    // 开始监听连接，backlog 表示等待队列的最大长度
+    if (::listen(this->server_fd, config.backlog) < 0) {
+        return std::unexpected(make_err(ErrCode::ListenFailed, errno));
+    }
+
+    return {};
+}
+```
+
+这部分代码体现了服务器网络层的基本工作过程：先创建 Socket，再绑定端口，最后进入监听状态，为后续客户端连接处理做准备。
+
+#### 4.2 客户端连接接收与线程池分发
+
+服务器启动后会进入 `Server::run()` 循环。该函数不断调用 `accept_connection()` 接收客户端连接，并将每个连接交给线程池处理。
+
+```cpp
+Result<void> run(Handler auto&& handler) {
+    while (true) {
+        // 阻塞等待客户端连接，成功后得到客户端 Socket 文件描述符
+        auto client_fd = accept_connection();
+        if (!client_fd) {
+            return std::unexpected(client_fd.error());
+        }
+
+        int fd = client_fd.value();
+
+        // 将连接处理任务提交到线程池，避免主线程被单个请求阻塞
+        this->thread_pool.submit([fd, &handler] {
+            // 将文件描述符封装为 Connection 对象，便于后续读写
+            Connection conn(fd);
+
+            // 调用 main.cpp 中传入的请求处理函数
+            auto res = handler(std::move(conn));
+            if (!res) {
+                // 当前版本中错误处理逻辑暂未展开
+            }
+        });
+    }
+
+    return {};
+}
+```
+
+线程池提交任务的核心代码如下：
+
+```cpp
+template <typename Fn>
+auto submit(Fn&& fn) -> Result<std::future<std::invoke_result_t<Fn>>> {
+    // 获取任务函数的返回类型
+    using ReturnType = std::invoke_result_t<Fn>;
+
+    // packaged_task 用于将普通函数包装成可以异步执行的任务
+    auto task = std::make_shared<std::packaged_task<ReturnType()>>(
+        std::forward<Fn>(fn));
+
+    // future 用于在需要时获取异步任务的执行结果
+    std::future<ReturnType> res = task->get_future();
+
+    {
+        std::lock_guard<std::mutex> lock(this->queue_mutex);
+        if (this->stop) {
+            return std::unexpected(make_err(ErrCode::ThreadPoolStop));
+        }
+
+        // 将任务加入任务队列，等待工作线程取出执行
+        this->tasks.emplace([task] { (*task)(); });
+    }
+
+    // 唤醒一个等待中的工作线程
+    condition.notify_one();
+    return res;
+}
+```
+
+通过该设计，主线程只负责接收连接，具体的请求处理由线程池中的工作线程完成，从而提高服务器并发处理能力。
+
+#### 4.3 HTTP 请求解析
+
+HTTP 请求解析由 `read_http_request()` 完成。它会先读取请求头，再解析请求行、请求路径、请求头字段和请求体。
+
+```cpp
+Result<HttpRequest> read_http_request(Connection& conn,
+                                      const HttpConfig& config) {
+    // 读取 HTTP 请求头。HTTP 头部以 \r\n\r\n 作为结束标志
+    auto header_res = conn.read_until("\r\n\r\n", config.max_header_size);
+    if (!header_res) {
+        return std::unexpected(header_res.error());
+    }
+
+    std::string header_txt = std::move(header_res.value());
+    std::string_view raw(header_txt);
+
+    // 去掉末尾的 \r\n\r\n，只保留真正的请求头内容
+    raw.remove_suffix(4);
+
+    HttpRequest req;
+
+    // 解析请求行，例如：GET /login.html HTTP/1.1
+    auto line_end = raw.find("\r\n");
+    std::string_view request_line =
+        line_end == std::string::npos ? raw : raw.substr(0, line_end);
+
+    auto sp1 = request_line.find(' ');
+    auto sp2 = request_line.find(' ', sp1 + 1);
+    if (sp1 == std::string::npos || sp2 == std::string::npos) {
+        return std::unexpected(make_err(ErrCode::InvalidHttpRequestLine));
+    }
+
+    // 解析请求方法，如 GET、POST 等
+    auto method_res = parse_method(request_line.substr(0, sp1));
+    if (!method_res) {
+        return std::unexpected(method_res.error());
+    }
+    req.method = method_res.value();
+
+    // 解析请求目标，例如 /log.html?date=2026_05_30
+    auto target_tmp = request_line.substr(sp1 + 1, sp2 - sp1 - 1);
+    auto query_pos = target_tmp.find('?');
+    std::string_view path_tmp = target_tmp.substr(0, query_pos);
+
+    req.target = std::string(target_tmp);
+    req.path = std::string(path_tmp);
+    if (query_pos != std::string_view::npos) {
+        req.query = std::string(target_tmp.substr(query_pos + 1));
+    }
+
+    // 校验 HTTP 版本，只支持 HTTP/1.0 和 HTTP/1.1
+    auto version_tmp = request_line.substr(sp2 + 1);
+    if (!is_supported_http_version(version_tmp)) {
+        return std::unexpected(make_err(ErrCode::HTTPVersionError));
+    }
+    req.version = std::string(version_tmp);
+
+    // 从第二行开始逐行解析请求头
+    size_t pos = line_end == std::string_view::npos ? raw.size() : line_end + 2;
+    while (pos < raw.size()) {
+        auto next = raw.find("\r\n", pos);
+        if (next == std::string::npos) {
+            next = raw.size();
+        }
+
+        std::string_view line = raw.substr(pos, next - pos);
+        auto header_res = parse_header_line(line);
+        if (!header_res) {
+            return std::unexpected(header_res.error());
+        }
+
+        // 同名请求头可能出现多次，因此 value 使用 vector 保存
+        req.headers[header_res->first].emplace_back(header_res->second);
+        pos = next + 2;
+    }
+
+    // 如果请求中存在 Content-Length，则继续读取指定长度的请求体
+    auto it = req.headers.find("content-length");
+    if (it != req.headers.end()) {
+        auto length_res = parse_content_length(it->second);
+        if (!length_res) {
+            return std::unexpected(length_res.error());
+        }
+
+        size_t body_length = length_res.value();
+        if (body_length > config.max_body_size) {
+            return std::unexpected(make_err(ErrCode::HttpBodyTooLarge));
+        }
+
+        auto body_res = conn.read_len(body_length);
+        if (!body_res) {
+            return std::unexpected(body_res.error());
+        }
+        req.body = std::move(body_res.value());
+    }
+
+    return req;
+}
+```
+
+该函数是 HTTP 模块的核心，它将客户端发送的原始字符串转换为程序内部使用的 `HttpRequest` 对象，为后续路由分发提供方法、路径、参数和请求体信息。
+
+#### 4.4 HTTP 响应构造
+
+HTTP 响应由 `HttpResponse::serialize()` 负责序列化。该函数将状态码、响应头和响应体拼接成浏览器可以识别的 HTTP 响应格式。
+
+```cpp
+std::string HttpResponse::serialize() const {
+    std::string data;
+
+    // 构造状态行，例如：HTTP/1.1 200 OK
+    data += "HTTP/1.1 ";
+    data += std::to_string(static_cast<int>(status));
+    data += " ";
+    data += reason_phrase(status);
+    data += "\r\n";
+
+    bool has_content_length = false;
+    bool has_connection = false;
+
+    // 写入已有响应头，同时检查是否已经包含 Content-Length 和 Connection
+    for (const auto& [name, values] : headers) {
+        if (header_name_equals(name, "Content-Length")) {
+            has_content_length = true;
+        }
+        if (header_name_equals(name, "Connection")) {
+            has_connection = true;
+        }
+
+        for (const auto& value : values) {
+            data += name;
+            data += ": ";
+            data += value;
+            data += "\r\n";
+        }
+    }
+
+    // 如果调用者没有设置 Content-Length，则自动根据响应体长度生成
+    if (!has_content_length) {
+        data += "Content-Length: ";
+        data += std::to_string(body.size());
+        data += "\r\n";
+    }
+
+    // 当前服务器采用短连接，每次响应结束后关闭连接
+    if (!has_connection) {
+        data += "Connection: close\r\n";
+    }
+
+    // 空行表示响应头结束，后面跟随响应体
+    data += "\r\n";
+    data += body;
+
+    return data;
+}
+```
+
+页面返回函数 `write_page()` 会从 `root/` 目录读取 HTML 文件，并通过 `write_html()` 返回给客户端。
+
+```cpp
+Result<void> write_page(Connection& conn, HttpStatus status,
+                        std::string_view filename) {
+    // 读取 root 目录下的 HTML 页面
+    std::string body = read_root_file(filename);
+
+    // 如果页面读取失败，则返回 500 错误
+    if (body.empty()) {
+        HttpResponse response{
+            .status = HttpStatus::InternalServerError,
+            .headers = {{"Content-Type", {"text/plain; charset=utf-8"}}},
+            .body = "Internal Server Error\n",
+        };
+        return conn.write_data(response.serialize());
+    }
+
+    // 正常情况下返回 HTML 页面
+    return write_html(conn, status, std::move(body));
+}
+```
+
+#### 4.5 请求路由与业务分发
+
+请求路由逻辑主要集中在 `main.cpp` 中。`handle_request()` 先调用 HTTP 模块解析请求，再根据请求方法分发到 GET 或 POST 处理函数。
+
+```cpp
+Result<void> handle_request(Connection conn, const AppConfig& config,
+                            Logger& logger) {
+    // 从连接中读取并解析 HTTP 请求
+    auto req_res = read_http_request(conn, config.http_config);
+    if (!req_res) {
+        logger.warn("bad request");
+        return write_page(conn, HttpStatus::BadRequest, "error.html");
+    }
+
+    const HttpRequest& req = req_res.value();
+
+    // 记录请求方法和请求目标，便于后续查看访问日志
+    logger.info(std::string(method_name(req.method)) + " " + req.target);
+
+    // 根据请求方法进入不同处理流程
+    if (req.method == HttpMethod::GET) {
+        return handle_get(conn, req.path, req.query, config, logger);
+    }
+    if (req.method == HttpMethod::POST) {
+        return handle_post(conn, req.path, req.body, config);
+    }
+
+    // 其他方法暂不支持，返回 405 错误
+    return write_page(conn, HttpStatus::MethodNotAllowed, "error.html");
+}
+```
+
+GET 请求主要用于返回页面或查询日志，POST 请求主要用于登录验证和配置修改。
+
+```cpp
+Result<void> handle_get(Connection& conn, std::string_view path,
+                        std::string_view query, const AppConfig& config,
+                        const Logger& logger) {
+    // 登录页，也是默认首页入口
+    if (path == "/" || path == "/login.html") {
+        return write_page(conn, HttpStatus::OK, "login.html");
+    }
+    if (path == "/index.html") {
+        return write_page(conn, HttpStatus::OK, "index.html");
+    }
+    if (path == "/config.html") {
+        return handle_config_get(conn, config);
+    }
+    if (path == "/log.html") {
+        return handle_log_get(conn, query, logger);
+    }
+
+    // 未匹配到的路径返回 404
+    return write_page(conn, HttpStatus::NotFound, "error.html");
+}
+
+Result<void> handle_post(Connection& conn, std::string_view path,
+                         std::string_view body, const AppConfig& config) {
+    // 登录表单提交
+    if (path == "/login") {
+        return handle_login_post(conn, body);
+    }
+
+    // 配置表单提交
+    if (path == "/config") {
+        return handle_config_post(conn, body, config);
+    }
+
+    return write_page(conn, HttpStatus::MethodNotAllowed, "error.html");
+}
+```
+
+这部分代码体现了本项目的业务分发方式：HTTP 模块只负责解析协议，真正的业务逻辑由 `main.cpp` 根据路径调用不同模块完成。
+
+#### 4.6 配置文件加载与保存
+
+配置模块负责从 `config/server.conf` 中读取服务器运行参数。配置文件采用 `key=value` 格式，因此加载过程的核心就是逐行读取、拆分键值、转换类型并写入 `AppConfig` 对象。
+
+```cpp
+Result<AppConfig> load_config(std::string_view path) {
+    std::ifstream fin{ std::string(path) };
+    if (!fin.is_open()) {
+        return std::unexpected(make_err(ErrCode::ConfigFileNotFound));
+    }
+
+    // 先使用默认配置，配置文件中出现的字段再覆盖默认值
+    AppConfig config = default_config();
+    std::string line;
+
+    while (std::getline(fin, line)) {
+        std::string_view view = trim(line);
+
+        // 空行和注释行不参与解析
+        if (view.empty() || view.front() == '#') {
+            continue;
+        }
+
+        // 配置项必须是 key=value 格式
+        auto eq = view.find('=');
+        if (eq == std::string_view::npos) {
+            return std::unexpected(make_err(ErrCode::ConfigParseFailed));
+        }
+
+        std::string_view key = trim(view.substr(0, eq));
+        std::string_view value = trim(view.substr(eq + 1));
+
+        if (key == "net.port") {
+            auto parsed = parse_int(value);
+            if (!parsed) {
+                return std::unexpected(make_err(ErrCode::ConfigParseFailed));
+            }
+            config.net_config.port = *parsed;
+        } else if (key == "http.max_body_size") {
+            auto parsed = parse_size(value);
+            if (!parsed) {
+                return std::unexpected(make_err(ErrCode::ConfigParseFailed));
+            }
+            config.http_config.max_body_size = *parsed;
+        } else if (key == "log.max_lines_per_file") {
+            auto parsed = parse_size(value);
+            if (!parsed) {
+                return std::unexpected(make_err(ErrCode::ConfigParseFailed));
+            }
+            config.log_config.max_lines = *parsed;
+        }
+    }
+
+    // 配置读取完成后统一校验，避免端口号、线程数等参数非法
+    if (auto res = valid_config(config); !res) {
+        return std::unexpected(res.error());
+    }
+
+    return config;
+}
+```
+
+配置保存函数将内存中的配置重新写回文件，使网页端修改后的配置可以持久化保存。
+
+```cpp
+Result<void> save_config(std::string_view path, const AppConfig& config) {
+    // 保存前先校验，避免非法配置写入文件
