+#### 4.1 Socket 创建、端口绑定与监听
+
+服务器启动的核心逻辑位于 `Server::start()`。该函数按照“创建 Socket、配置 Socket、绑定端口并监听”的顺序完成服务器初始化。
+
+```cpp
+Result<void> Server::start() {
+    // 如果 server_fd 已经不是 -1，说明服务器已经启动过，不能重复启动
+    if (this->server_fd != -1) {
+        return std::unexpected(make_err(ErrCode::ServerAlreadyStarted));
+    }
+
+    // 创建服务器 Socket，成功后返回文件描述符
+    auto res = create_server();
+    if (!res) {
+        return std::unexpected(res.error());
+    }
+
+    // 保存服务器 Socket 文件描述符，后续 bind、listen、accept 都依赖它
+    this->server_fd = res.value();
+
+    // 配置 Socket 选项，例如是否允许端口复用
+    if (auto config_res = config_server(); !config_res) {
+        return std::unexpected(config_res.error());
+    }
+
+    // 将 Socket 绑定到指定端口，并开始监听客户端连接
+    if (auto bind_res = bind_and_listen(); !bind_res) {
+        return std::unexpected(bind_res.error());
+    }
+
+    return {};
+}
+```
+
+其中，`create_server()` 负责调用系统接口创建 TCP Socket，`bind_and_listen()` 负责绑定端口并进入监听状态。
+
+```cpp
+Result<int> Server::create_server() {
+    // AF_INET 表示使用 IPv4，SOCK_STREAM 表示使用 TCP 字节流
+    int fd = ::socket(AF_INET, SOCK_STREAM, 0);
+    if (fd == -1) {
+        return std::unexpected(make_err(ErrCode::SocketCreateFailed, errno));
+    }
+    return fd;
+}
+
+Result<void> Server::bind_and_listen() {
+    sockaddr_in address{};
+    address.sin_family = AF_INET;           // 使用 IPv4 地址族
+    address.sin_addr.s_addr = INADDR_ANY;   // 监听本机所有网卡地址
+    address.sin_port = htons(config.port);  // 将端口号转换为网络字节序
+
+    // 将服务器 Socket 绑定到指定 IP 和端口
+    if (::bind(this->server_fd, reinterpret_cast<struct sockaddr*>(&address),
+               sizeof(address)) < 0) {
+        return std::unexpected(make_err(ErrCode::BindFailed, errno));
+    }
+
+    // 开始监听连接，backlog 表示等待队列的最大长度
+    if (::listen(this->server_fd, config.backlog) < 0) {
+        return std::unexpected(make_err(ErrCode::ListenFailed, errno));
+    }
+
+    return {};
+}
+```
+
+这部分代码体现了服务器网络层的基本工作过程：先创建 Socket，再绑定端口，最后进入监听状态，为后续客户端连接处理做准备。
