+#### 4.3 HTTP 请求解析
+
+HTTP 请求解析由 `read_http_request()` 完成。它会先读取请求头，再解析请求行、请求路径、请求头字段和请求体。
+
+```cpp
+Result<HttpRequest> read_http_request(Connection& conn,
+                                      const HttpConfig& config) {
+    // 读取 HTTP 请求头。HTTP 头部以 \r\n\r\n 作为结束标志
+    auto header_res = conn.read_until("\r\n\r\n", config.max_header_size);
+    if (!header_res) {
+        return std::unexpected(header_res.error());
+    }
+
+    std::string header_txt = std::move(header_res.value());
+    std::string_view raw(header_txt);
+
+    // 去掉末尾的 \r\n\r\n，只保留真正的请求头内容
+    raw.remove_suffix(4);
+
+    HttpRequest req;
+
+    // 解析请求行，例如：GET /login.html HTTP/1.1
+    auto line_end = raw.find("\r\n");
+    std::string_view request_line =
+        line_end == std::string::npos ? raw : raw.substr(0, line_end);
+
+    auto sp1 = request_line.find(' ');
+    auto sp2 = request_line.find(' ', sp1 + 1);
+    if (sp1 == std::string::npos || sp2 == std::string::npos) {
+        return std::unexpected(make_err(ErrCode::InvalidHttpRequestLine));
+    }
+
+    // 解析请求方法，如 GET、POST 等
+    auto method_res = parse_method(request_line.substr(0, sp1));
+    if (!method_res) {
+        return std::unexpected(method_res.error());
+    }
+    req.method = method_res.value();
+
+    // 解析请求目标，例如 /log.html?date=2026_05_30
+    auto target_tmp = request_line.substr(sp1 + 1, sp2 - sp1 - 1);
+    auto query_pos = target_tmp.find('?');
+    std::string_view path_tmp = target_tmp.substr(0, query_pos);
+
+    req.target = std::string(target_tmp);
+    req.path = std::string(path_tmp);
+    if (query_pos != std::string_view::npos) {
+        req.query = std::string(target_tmp.substr(query_pos + 1));
+    }
+
+    // 校验 HTTP 版本，只支持 HTTP/1.0 和 HTTP/1.1
+    auto version_tmp = request_line.substr(sp2 + 1);
+    if (!is_supported_http_version(version_tmp)) {
+        return std::unexpected(make_err(ErrCode::HTTPVersionError));
+    }
+    req.version = std::string(version_tmp);
+
+    // 从第二行开始逐行解析请求头
+    size_t pos = line_end == std::string_view::npos ? raw.size() : line_end + 2;
+    while (pos < raw.size()) {
+        auto next = raw.find("\r\n", pos);
+        if (next == std::string::npos) {
+            next = raw.size();
+        }
+
+        std::string_view line = raw.substr(pos, next - pos);
+        auto header_res = parse_header_line(line);
+        if (!header_res) {
+            return std::unexpected(header_res.error());
+        }
+
+        // 同名请求头可能出现多次，因此 value 使用 vector 保存
+        req.headers[header_res->first].emplace_back(header_res->second);
+        pos = next + 2;
+    }
+
+    // 如果请求中存在 Content-Length，则继续读取指定长度的请求体
+    auto it = req.headers.find("content-length");
+    if (it != req.headers.end()) {
+        auto length_res = parse_content_length(it->second);
+        if (!length_res) {
+            return std::unexpected(length_res.error());
+        }
+
+        size_t body_length = length_res.value();
+        if (body_length > config.max_body_size) {
+            return std::unexpected(make_err(ErrCode::HttpBodyTooLarge));
+        }
+
+        auto body_res = conn.read_len(body_length);
+        if (!body_res) {
+            return std::unexpected(body_res.error());
+        }
+        req.body = std::move(body_res.value());
+    }
+
+    return req;
+}
+```
+
+该函数是 HTTP 模块的核心，它将客户端发送的原始字符串转换为程序内部使用的 `HttpRequest` 对象，为后续路由分发提供方法、路径、参数和请求体信息。
+
+#### 4.4 HTTP 响应构造
+
+HTTP 响应由 `HttpResponse::serialize()` 负责序列化。该函数将状态码、响应头和响应体拼接成浏览器可以识别的 HTTP 响应格式。
+
+```cpp
+std::string HttpResponse::serialize() const {
+    std::string data;
+
+    // 构造状态行，例如：HTTP/1.1 200 OK
+    data += "HTTP/1.1 ";
+    data += std::to_string(static_cast<int>(status));
+    data += " ";
+    data += reason_phrase(status);
+    data += "\r\n";
+
+    bool has_content_length = false;
+    bool has_connection = false;
+
+    // 写入已有响应头，同时检查是否已经包含 Content-Length 和 Connection
+    for (const auto& [name, values] : headers) {
+        if (header_name_equals(name, "Content-Length")) {
+            has_content_length = true;
+        }
+        if (header_name_equals(name, "Connection")) {
+            has_connection = true;
+        }
+
+        for (const auto& value : values) {
+            data += name;
+            data += ": ";
+            data += value;
+            data += "\r\n";
+        }
+    }
+
+    // 如果调用者没有设置 Content-Length，则自动根据响应体长度生成
+    if (!has_content_length) {
+        data += "Content-Length: ";
+        data += std::to_string(body.size());
+        data += "\r\n";
+    }
+
+    // 当前服务器采用短连接，每次响应结束后关闭连接
+    if (!has_connection) {
+        data += "Connection: close\r\n";
+    }
+
+    // 空行表示响应头结束，后面跟随响应体
+    data += "\r\n";
+    data += body;
+
+    return data;
+}
+```
