+    // 配置表单提交
+    if (path == "/config") {
+        return handle_config_post(conn, body, config);
+    }
+
+    return write_page(conn, HttpStatus::MethodNotAllowed, "error.html");
+}
+```
+
+这部分代码体现了本项目的业务分发方式：HTTP 模块只负责解析协议，真正的业务逻辑由 `main.cpp` 根据路径调用不同模块完成。
+
+#### 4.6 配置文件加载与保存
+
+配置模块负责从 `config/server.conf` 中读取服务器运行参数。配置文件采用 `key=value` 格式，因此加载过程的核心就是逐行读取、拆分键值、转换类型并写入 `AppConfig` 对象。
+
+```cpp
+Result<AppConfig> load_config(std::string_view path) {
+    std::ifstream fin{ std::string(path) };
+    if (!fin.is_open()) {
+        return std::unexpected(make_err(ErrCode::ConfigFileNotFound));
+    }
+
+    // 先使用默认配置，配置文件中出现的字段再覆盖默认值
+    AppConfig config = default_config();
+    std::string line;
+
+    while (std::getline(fin, line)) {
+        std::string_view view = trim(line);
+
+        // 空行和注释行不参与解析
+        if (view.empty() || view.front() == '#') {
+            continue;
+        }
+
+        // 配置项必须是 key=value 格式
+        auto eq = view.find('=');
+        if (eq == std::string_view::npos) {
+            return std::unexpected(make_err(ErrCode::ConfigParseFailed));
+        }
+
+        std::string_view key = trim(view.substr(0, eq));
+        std::string_view value = trim(view.substr(eq + 1));
+
+        if (key == "net.port") {
+            auto parsed = parse_int(value);
+            if (!parsed) {
+                return std::unexpected(make_err(ErrCode::ConfigParseFailed));
+            }
+            config.net_config.port = *parsed;
+        } else if (key == "http.max_body_size") {
+            auto parsed = parse_size(value);
+            if (!parsed) {
+                return std::unexpected(make_err(ErrCode::ConfigParseFailed));
+            }
+            config.http_config.max_body_size = *parsed;
+        } else if (key == "log.max_lines_per_file") {
+            auto parsed = parse_size(value);
+            if (!parsed) {
+                return std::unexpected(make_err(ErrCode::ConfigParseFailed));
+            }
+            config.log_config.max_lines = *parsed;
+        }
+    }
+
+    // 配置读取完成后统一校验，避免端口号、线程数等参数非法
+    if (auto res = valid_config(config); !res) {
+        return std::unexpected(res.error());
+    }
+
+    return config;
+}
+```
+
+配置保存函数将内存中的配置重新写回文件，使网页端修改后的配置可以持久化保存。
+
+```cpp
+Result<void> save_config(std::string_view path, const AppConfig& config) {
+    // 保存前先校验，避免非法配置写入文件
+    if (auto res = valid_config(config); !res) {
+        return std::unexpected(res.error());
+    }
+
+    std::ofstream fout{ std::string(path) };
+    if (!fout.is_open()) {
+        return std::unexpected(make_err(ErrCode::ConfigSaveFailed));
+    }
+
+    // 按固定 key=value 格式写回配置文件
+    fout << "net.port=" << config.net_config.port << '\n';
+    fout << "net.backlog=" << config.net_config.backlog << '\n';
+    fout << "net.worker_count=" << config.net_config.worker_count << '\n';
+    fout << "net.reuseAddress="
+         << (config.net_config.reuseAddress ? "true" : "false") << '\n';
+    fout << "http.max_body_size=" << config.http_config.max_body_size << '\n';
+    fout << "http.max_header_size=" << config.http_config.max_header_size << '\n';
+    fout << "log.max_lines_per_file=" << config.log_config.max_lines << '\n';
+
+    if (!fout) {
+        return std::unexpected(make_err(ErrCode::ConfigSaveFailed));
+    }
+
+    return {};
+}
+```
+
+#### 4.7 异步日志写入与日志轮转
+
+日志模块使用单独的后台线程写入日志。业务线程只负责把日志消息放入队列，真正的磁盘写入由 `Logger::run()` 完成。
+
+```cpp
+void Logger::run() {
+    while (true) {
+        std::queue<LogEntry> local_queue;
+
+        {
+            std::unique_lock<std::mutex> lock(this->mutex);
+
+            // 当日志队列为空时，日志线程进入等待状态，避免空转消耗 CPU
+            this->condition.wait(lock, [this] {
+                return this->stop || !this->queue.empty();
+            });
+
+            // 如果收到停止信号并且队列为空，说明所有日志已写完，可以退出线程
+            if (this->stop && this->queue.empty()) {
+                return;
+            }
+
+            // 将共享队列交换到局部队列，减少持锁时间
+            local_queue.swap(this->queue);
+        }
+
+        while (!local_queue.empty()) {
+            const auto& entry = local_queue.front();
+            auto now = std::chrono::system_clock::now();
+            std::string date = Logger::date_string(now);
+
+            // 写入前检查是否需要按日期或行数切换日志文件
+            this->rotate_if_needed(date);
+
+            if (this->output.is_open()) {
+                this->output << Logger::timestamp_string(now) << " ["
+                             << Logger::level_name(entry.level) << "]: "
+                             << entry.message << '\n';
+                ++this->current_line_count;
+            }
+
+            local_queue.pop();
+        }
+
+        // 批量写入后统一刷新文件
+        this->output.flush();
+    }
+}
+```
+
+日志轮转逻辑如下：当日期发生变化时创建新的日期目录；当当前文件行数达到上限时，切换到下一个日志文件。
+
+```cpp
+void Logger::rotate_if_needed(const std::string& date) {
+    // 日期变化时，关闭旧文件并切换到新日期目录
+    if (this->current_date != date) {
+        if (this->output.is_open()) {
+            this->output.close();
+        }
+
+        this->current_date = date;
+        this->current_file_index = 0;
+        this->current_line_count = 0;
+        this->open_output(date, this->current_file_index);
+        return;
+    }
+
+    // 如果当前没有打开日志文件，则重新打开
+    if (!this->output.is_open()) {
+        this->open_output(date, this->current_file_index);
+        return;
+    }
+
+    // 当前日志文件行数达到上限时，创建下一个日志文件
+    if (this->current_line_count >= this->max_lines_per_file) {
+        this->output.close();
+        ++this->current_file_index;
+        this->current_line_count = 0;
+        this->open_output(date, this->current_file_index);
+    }
+}
+```
+
+#### 4.8 用户认证实现
+
+用户认证由 `Authenticator::auth()` 完成。用户文件采用 `username:password` 格式保存，每次认证时逐行读取并查找匹配的用户名。
+
+```cpp
+bool Authenticator::auth(const std::string& username, std::string& password) {
+    bool ok = false;
+
+    // 以二进制方式打开用户文件，避免平台换行符处理带来额外影响
+    std::ifstream file{file_path, std::ios::binary};
+    if (file) {
+        while (read_buffer(file)) {
+            // 每一行使用 ':' 分隔用户名和密码
+            char* separator = std::strchr(buffer.data(), ':');
+            if (separator == nullptr) {
+                wipe(buffer.data(), buffer.size());
+                continue;
+            }
+
+            // 将 ':' 替换为字符串结束符，使 buffer 前半部分成为用户名
+            *separator = '\0';
+            const char* stored_username = buffer.data();
+            const char* stored_password = separator + 1;
+
+            // 用户名匹配后，再比较密码
+            if (username == stored_username) {
+                ok = constant_time_equal(stored_password, password);
+                wipe(buffer.data(), buffer.size());
+                break;
+            }
+
+            // 每次处理完一行都清空缓冲区，减少敏感信息残留
+            wipe(buffer.data(), buffer.size());
+        }
+    }
+
+    // 函数结束前清理缓冲区和用户输入的密码
+    wipe(buffer.data(), buffer.size());
+    wipe_password(password);
+    return ok;
+}
+```
+
+密码比较函数使用常量时间比较方式，尽量避免因为比较提前结束而泄露密码匹配位置。
+
+```cpp
+bool Authenticator::constant_time_equal(const char* stored_password,
+                                        const std::string& password) {
+    const std::size_t stored_size = std::strlen(stored_password);
+    auto diff = stored_size ^ password.size();
+    const std::size_t max_size =
+        stored_size > password.size() ? stored_size : password.size();
+
+    // 不在第一个不同字符处提前返回，而是始终遍历完整长度
+    for (std::size_t i = 0; i < max_size; ++i) {
+        const auto stored =
+            i < stored_size ? static_cast<unsigned char>(stored_password[i]) : 0;
+        const auto input =
+            i < password.size() ? static_cast<unsigned char>(password[i]) : 0;
+        diff |= stored ^ input;
+    }
+
+    return diff == 0;
+}
+```
+
+这部分代码体现了认证模块的两个重点：一是从用户文件中查找账号密码，二是在认证完成后主动清理密码相关内存，减少敏感数据在内存中残留的时间。
